const ROOMS=[
{id:'laundry',n:'01',name:'暮らしの小さな実験室',short:'衣類と洗濯',en:'EVERYDAY, REIMAGINED',image:'laundry',color:'#e7e9de',ink:'#3f665a',title:'一枚の服から、\n暮らしを整える。',desc:'たたむ、干す、しまう。手を動かしながら、日常の小さな仕組みを知る。',start:'fold'},
{id:'cooking',n:'02',name:'料理の「なぜ？」と基本技',short:'料理の基本',en:'A LITTLE KITCHEN SCIENCE',image:'kitchen',color:'#eee1ce',ink:'#8d592d',title:'おいしいは、\n小さな発見の積み重ね。',desc:'火加減も、味付けも。最初の一皿を、実験のように楽しもう。',start:'eggs'},
{id:'tools',n:'03',name:'道具のしくみ博物館',short:'道具のしくみ',en:'THE SECRET LIFE OF OBJECTS',image:'tools',color:'#e4e4d9',ink:'#655c37',title:'いつもの道具に、\n知らない原理が隠れている。',desc:'冷やす箱、静かにする音。便利の向こう側を、少しだけのぞいてみる。',start:'noise'},
{id:'communication',n:'04',name:'人に伝わる言葉の研究室',short:'伝わる言葉',en:'WORDS THAT CONNECT',image:'writing',color:'#e5e7ed',ink:'#535f7b',title:'伝えることは、\n相手の景色を想像すること。',desc:'言い換え、たとえ、説明の順番。使ってみたくなる言葉の道具を集める。',start:'plain'},
{id:'mind',n:'05',name:'人はなぜ、そう感じる？',short:'感じ方の不思議',en:'A WINDOW INTO THE MIND',image:'forest',color:'#e9e1eb',ink:'#795978',title:'当たり前の感覚にも、\nまだ知らない裏側がある。',desc:'迷う、見る、受け取る。自分にも他人にも、決めつけないための好奇心。',start:'choice'},
{id:'civilization',n:'06',name:'文明の生活史',short:'文明と暮らし',en:'HOW PEOPLE MADE A WORLD',image:'history',color:'#eae1d3',ink:'#8a643d',title:'人は、どうやって\n暮らしの約束をつくった？',desc:'時刻、お金、ことば。制度の奥から、そこに生きていた人の毎日を見る。',start:'railtime'},
{id:'nature',n:'07',name:'生きものと自然の変な戦略',short:'自然の戦略',en:'NATURE FINDS A WAY',image:'jelly',color:'#dce8de',ink:'#3b6e55',title:'世界には、まだ\nこんな生き方がある。',desc:'隠れる、光る、色をつくる。多様な自然を、驚きと一緒に観察する。',start:'camouflage'},
{id:'play',n:'08',name:'身近な遊びの奥にあるもの',short:'遊びの奥側',en:'PLAY IS A WAY OF KNOWING',image:'ocean',color:'#dfe9ed',ink:'#396c81',title:'好きな遊びから、\n知らない世界へ。',desc:'変化球と空気、ゲームと偶然。楽しさを入口に、物理や数学へ寄り道する。',start:'curveball'}
];
function roomIndex(){return `<section class="room-index" aria-label="あなたの好奇心から選ぶ8つの展示室"><div class="section-heading"><div><div class="eyebrow">EIGHT WAYS TO WONDER</div><h2>暮らしも、世界も。気になるほうへ。</h2><p>手を動かす日も、ただ眺める日も。8つの展示室ができました。</p></div><span class="room-count">08 ROOMS<br>NO RIGHT ORDER</span></div><div class="room-directory">${ROOMS.map(r=>`<a class="room-entry" href="#room-${r.id}" style="--room:${r.color};--room-ink:${r.ink}"><span class="room-number">${r.n}</span><div><small>${r.en}</small><h3>${r.short}</h3></div><span class="room-symbol">${({laundry:'↳',cooking:'◒',tools:'≈',communication:'“',mind:'◉',civilization:'⌁',nature:'✳',play:'↗'})[r.id]}</span><span class="room-entry-arrow">↗</span></a>`).join('')}</div></section>`}
function roomPage(id){const r=ROOMS.find(r=>r.id===id);if(!r)return discover();const items=data.filter(a=>a.rooms?.includes(id));return `<div class="page room-page" style="--room:${r.color};--room-ink:${r.ink}"><a class="text-link" href="#discover">← 探検の入口へ</a><section class="room-cover"><div class="room-cover-copy"><div class="eyebrow">ROOM ${r.n} / ${r.en}</div><h1>${r.title.split('\n').map(esc).join('<br>')}</h1><p>${r.desc}</p><button class="primary" data-article="${r.start}">最初の展示をのぞく　↗</button><span class="room-cover-n">${r.n}</span></div><img src="./assets/${r.image}.jpg" alt="${r.short}のイメージ写真"></section>${heading('FOLLOW A LITTLE QUESTION',r.name,`${items.length} の展示 · 好きなものから、好きなだけ。`)}<div class="exhibits">${items.map(card).join('')}</div><div class="room-side-note"><span>↗</span><p>${id==='laundry'||id==='cooking'?'「覚えなきゃ」より、ひとつ試してみる。図解は自分のペースで進められます。':'ここでの知識を何に使うかは、あなたの自由。創作への転用も、ただ楽しむだけでも。'}</p></div><div class="room-neighbors"><p class="eyebrow">THE NEXT DOOR IS ALWAYS OPEN</p>${ROOMS.filter(x=>x.id!==id).map(x=>`<a href="#room-${x.id}">${x.short} ↗</a>`).join('')}</div></div>`}
const WALKTHROUGHS={
shirt:{title:'Tシャツ',steps:[['広げて、形を見る','乾いたTシャツを、背中を上にして平らに広げます。しわを手で軽く伸ばします。'],['左右を内側へ','収納に合う幅を決めて、左右の袖と身頃を内側へ。まず細長い長方形にします。'],['裾を持ち上げる','収納の高さに合わせて、裾側から二つ折りか三つ折りにします。図は二つ折りの例です。'],['大きさを確かめる','引き出しの高さに入るか確認。立てる場合は、倒れにくい幅に調整します。']]},
pants:{title:'ズボン',steps:[['両脚をそろえる','ズボンを平らに置き、左右の脚を重ねます。ポケットや裾のしわも軽く整えます。'],['出っ張りを内側に','股の出っ張りを内側へ折り、できるだけ長方形に整えます。'],['丈を折る','裾からウエスト側へ折ります。長いものは三つ折りなど、収納に合う回数にします。'],['収納に合わせる','高さと厚さを確かめてしまいます。折りじわが気になる素材は、掛ける収納も検討できます。']]},
towel:{title:'タオル',steps:[['広げる','乾いたタオルを平らに広げます。これは長方形をそろえる練習用の基本例です。'],['長い辺を半分に','長い辺が半分になるように折り、端をそろえます。'],['もう一度、半分に','今度は残った長い辺を半分にします。棚に合わなければ三つ折りでも構いません。'],['置く幅に合わせる','棚の奥行きや使う順番に合わせて置きます。正解の大きさは、しまう場所によって変わります。']]}
};
const RECIPES={eggs:{label:'編集部の練習用レシピ / 1人分',ingredients:['卵 1個','食用油 小さじ1','塩 少々（好みで）'],tools:'フライパン・ボウル・箸かへら・皿',steps:[['先に、準備する','手を洗い、卵をボウルに割り入れて、白身と黄身が混ざるまでほぐします。塩を使うならここで少量。生卵に触れたら手を洗います。'],['弱めの火から','フライパンに油を広げ、弱めの中火で温めます。油を煙が出るまで熱する必要はありません。卵液を流し入れます。'],['固まった端から、混ぜる','端が固まり始めたら、へらで中央へ寄せるように混ぜます。焦げそうなら火を弱めます。液状の卵を残さず、全体に火を通します。'],['皿へ、いただきます','卵全体が固まったら火を止め、皿へ移します。調理時間は鍋や火力で変わります。加熱できていることを確認し、作ったら早めに食べます。']]},salad:{label:'編集部の練習用アレンジ / 1〜2人分',ingredients:['きゅうり 1本','ツナ缶 1缶（約70g）','しょうゆ 小さじ1/2から','ごま油 小さじ1/2（好みで）'],tools:'清潔なまな板・包丁・ボウル・スプーン',steps:[['洗って、準備する','手ときゅうりを洗います。きゅうりは両端を切り、食べやすい薄切りに。包丁の刃の下に指を入れず、急がず切ります。'],['汁をきって合わせる','ツナの汁をきり、きゅうりとボウルに入れます。缶の縁や切り口に注意してください。'],['少しずつ、和える','しょうゆ小さじ1/2を加えて混ぜます。好みでごま油を小さじ1/2。缶の塩分や油の有無で味が変わるため、最初から多く入れません。'],['味を見て、盛りつける','清潔なスプーンで少量を味見し、足りなければしょうゆを少し足します。盛りつけたら早めに食べます。参考の公式レシピとは分量・切り方が異なります。']]}}
function foldDrawing(kind,i){let shape='';const dashed='stroke="#ad7650" stroke-width="2" stroke-dasharray="6 6" fill="none"';if(kind==='shirt'){shape=i===0?'<path d="M112 55l47-20q21 28 42 0l47 20 35 57-38 21-16-29v120H131V104l-16 29-38-21Z" fill="#a3b9a1" stroke="#52715a" stroke-width="2"/><path d="M144 70v145M216 70v145" '+dashed+'/><path d="M101 163h24m-7-7 7 7-7 7m141-7h-24m7-7-7 7 7 7" stroke="#ad7650" stroke-width="3" fill="none"/>':i===1?'<rect x="139" y="42" width="82" height="182" rx="5" fill="#a3b9a1" stroke="#52715a" stroke-width="2"/><path d="M143 85l37 25 37-25M139 133h82" '+dashed+'/><path d="M245 197q38-44 0-77m-7 11 7-11 11 6" stroke="#ad7650" stroke-width="3" fill="none"/>':'<rect x="133" y="88" width="94" height="112" rx="7" fill="#a3b9a1" stroke="#52715a" stroke-width="2"/><path d="M139 100h82M146 108h67" stroke="#d4e0cf" stroke-width="3"/>'}
else if(kind==='pants'){shape=i===0?'<path d="M140 36h90l14 193h-49l-10-103-12 103h-50Z" fill="#9cabb9" stroke="#536a7d" stroke-width="2"/><path d="M140 57h90M185 59v67" stroke="#536a7d" stroke-width="2"/>':i===1?'<path d="M153 38h64v188h-67l12-97-17-16 15-17Z" fill="#9cabb9" stroke="#536a7d" stroke-width="2"/><path d="M155 132h62" '+dashed+'/>':'<rect x="146" y="85" width="73" height="115" rx="5" fill="#9cabb9" stroke="#536a7d" stroke-width="2"/><path d="M151 98h62" stroke="#dce1e3" stroke-width="4"/>'}
else{shape=i===0?'<rect x="71" y="65" width="218" height="134" rx="4" fill="#d7bd8d" stroke="#937749" stroke-width="2"/><path d="M180 65v134" '+dashed+'/>':i===1?'<rect x="127" y="63" width="106" height="138" rx="4" fill="#d7bd8d" stroke="#937749" stroke-width="2"/><path d="M127 132h106" '+dashed+'/>':'<rect x="128" y="101" width="104" height="72" rx="5" fill="#d7bd8d" stroke="#937749" stroke-width="2"/><path d="M135 111h90M135 120h90" stroke="#eadbc2" stroke-width="3"/>'}return `<svg viewBox="0 0 360 265" role="img" aria-label="${WALKTHROUGHS[kind].title}の手順${i+1}の模式図"><ellipse cx="180" cy="236" rx="89" ry="9" fill="#203e2510"/>${shape}<text x="180" y="256" text-anchor="middle" fill="#7a816e" font-size="10">${i<2?'破線は折る位置の目安':'仕上がりの模式図・収納に合わせて調整'}</text></svg>`}
function recipeDrawing(id,i){const pan=id==='eggs';return `<svg viewBox="0 0 360 240" role="img" aria-label="${pan?'卵料理':'きゅうりとツナ'}の工程${i+1}の模式図"><ellipse cx="175" cy="159" rx="99" ry="43" fill="${pan?'#d3d6cf':'#e4e9e2'}" stroke="#6c7b6a" stroke-width="3"/>${pan?'<path d="M263 167l53 22" stroke="#5d675d" stroke-width="15" stroke-linecap="round"/>':''}<ellipse cx="175" cy="146" rx="85" ry="34" fill="${pan?(i===0?'#f3e9c9':i===1?'#efc45f':'#e7b642'):'#cbdcbe'}"/>${pan?(i===0?'<ellipse cx="175" cy="145" rx="23" ry="17" fill="#e4a82e"/>':'<path d="M112 144q23-28 47 0t53 0q20 16 33 0M124 160q28-22 45-4t54-1" stroke="#f6dc86" stroke-width="8" fill="none"/>'):'<g fill="#82a372" stroke="#557a4d">'+[0,1,2,3,4,5].map(k=>`<ellipse cx="${121+k%3*50}" cy="${135+Math.floor(k/3)*22}" rx="18" ry="10"/>`).join('')+'</g>'}${i===2?'<path d="M224 92l-54 49" stroke="#927357" stroke-width="8" stroke-linecap="round"/><path d="M107 94q64-34 126 0" stroke="#ae8857" stroke-dasharray="5 5" stroke-width="2" fill="none"/>':''}<text x="180" y="224" text-anchor="middle" fill="#8d7963" font-size="10">工程を表す図です・加熱状態は実物で確認</text></svg>`}
function articleExperience(a){const t=a.interactive;if(!t)return '';let body='';if(t==='fold')body='<div class="experience-tabs" role="group" aria-label="たたむもの"><button class="active" data-fold-kind="shirt">Tシャツ</button><button data-fold-kind="pants">ズボン</button><button data-fold-kind="towel">タオル</button></div><div id="walkthrough"></div>';
else if(t==='eggs'||t==='salad'){const r=RECIPES[t];body=`<p class="fine">${r.label}</p><div class="ingredient-list">${r.ingredients.map(x=>`<label><input type="checkbox">${esc(x)}</label>`).join('')}</div><p class="fine">道具：${r.tools}</p><div id="walkthrough"></div>`}
else if(t==='noise')body='<p>灰色の音に、緑の音を重ねます。逆向きの波（180°）にすると、下の合成波はどうなるでしょう。</p><svg id="noise-plot" viewBox="0 0 540 235" role="img" aria-label="二つの正弦波と合成波"></svg><label class="control">重ねる波のずれ <input id="phase" type="range" min="0" max="360" value="0"><output id="phase-out">0°</output></label><p class="fine">同じ大きさ・同じ周波数の二つの波だけの理想モデル。音は鳴りません。</p>';
else if(t==='plain')body='<p class="fine">携帯サービスを例にした編集部の作例。実際のプランの条件・速度を表すものではありません。</p><div class="experience-tabs"><button data-explain="0" class="active">用語だけ</button><button data-explain="1">言い換える</button><button data-explain="2">たとえと限界</button></div><div id="explain-example" class="experience-example"></div>';
else if(t==='teachback')body='<div class="speech-bubble">私の説明が分かりにくくなかったか確認したいので、明日最初にする操作を、あなたの言葉で教えてもらえますか。</div><p class="fine">応用の作例。相手が言えなければ責めずに、説明の仕方を変えてみます。</p><details><summary>うまく伝わらなかったときの言い方</summary><p>「ありがとうございます。ここは説明を補いますね。まず一つ目だけ、一緒にやってみましょう。」</p></details>';
else if(t==='choice')body='<label for="choice-axis">今、何を重視する？</label><select id="choice-axis"><option value="all">まだ決めていない</option><option value="quick">短い時間で試したい</option><option value="wonder">不思議な話を知りたい</option></select><div id="choice-options" class="choice-options"></div><p class="fine">自分の感覚を眺める展示です。選択肢の数による能力・性格・効果の測定はしません。</p>';
else if(t==='heat')body='<div class="heat-flow"><span>庫内の熱<br><b>吸収する</b></span><i>→</i><span>冷媒の循環<br><b>電気を使う</b></span><i>→</i><span>部屋の空気へ<br><b>放出する</b></span></div><p class="fine">熱の移動の模式図。機種ごとの構造や設置条件は説明書へ。</p>';
else if(t==='drying')body='<div class="drying-model" id="drying-model"><span>▰</span><span>▰</span><span>▰</span><span>▰</span><span>▰</span></div><button class="secondary" id="space-laundry">布の間をあけてみる ↔</button><p class="fine">配置の模式図です。乾く速さを数値で予測するものではありません。</p>';
else if(t==='curveball')body='<svg id="ball-plot" viewBox="0 0 540 210" role="img" aria-label="回転方向で変化する模式的なボールの軌道"></svg><label class="control">回転の向きのモデル <input type="range" min="-1" max="1" step="1" value="0" id="spin"><output id="spin-out">回転なし</output></label><p class="fine">力の向きの考え方を示す模式図。重力、縫い目、実際の速度や回転数を計算していません。</p>';
else if(t==='timeline')body='<div class="history-lens"><div><small>町の時刻</small><p>その土地の太陽を基準にする。</p></div><span>→</span><div><small>共通の時刻</small><p>離れた町の予定を、一つの基準で合わせる。</p></div></div><p>もし町ごとに時刻が違ったら、待ち合わせや配送はどう変わるでしょう。制度が変わるときの暮らしを想像してみてください。</p>';
else if(t==='money')body='<div class="experience-example"><small>暮らしから考える問い</small><h3>「受け取ってもいい」と<br>思えるのは、どんなとき？</h3><p>素材の使い道、ほかの人も受け取るという期待、記録や発行者への信頼。地域や制度によって、支えるものは変わります。</p></div>';
else if(t==='camouflage')body='<div class="camouflage-model" id="camouflage-model"><svg viewBox="0 0 350 140" role="img" aria-label="背景に似た葉の模式図"><path d="M140 110Q55 30 210 24Q249 100 140 110Z" fill="#8b9a64" stroke="#677b52" stroke-width="2"/><path d="M120 120l78-80" stroke="#65704b" stroke-width="3"/></svg></div><button class="secondary" id="change-background">背景を変えてみる</button><p class="fine">背景との似方を観察するための図です。特定の生物の擬態や、人以外の視覚を再現するものではありません。</p>';
return body?`<section class="article-experience" data-experience="${t}"><div class="eyebrow">${['fold','eggs','salad'].includes(t)?'LOOK. TRY. TAKE YOUR TIME.':'A LITTLE HANDS-ON DISCOVERY'}</div><h2>${({fold:'一手順ずつ、一緒に。',eggs:'最初の一皿を、ここから。',salad:'材料をそろえて、始めよう。',noise:'波をずらして、重ねてみる。',plain:'同じことを、違う伝え方で。',teachback:'こんな聞き方も、できる。',choice:'選ぶ前に、軸をひとつ。',heat:'熱の行き先をたどる。',drying:'空気が通る、すき間をつくる。',curveball:'回転と軌道を眺める。',timeline:'町の暮らしから、制度を見る。',money:'約束を、少しだけ考える。',camouflage:'背景が変わると、見え方も変わる。'})[t]}</h2>${body}</section>`:''}
function setupArticleExperience(a){const t=a.interactive;if(!t)return;let step=0,kind='shirt';function walkthrough(){const r=t==='fold'?WALKTHROUGHS[kind]:RECIPES[t],s=r.steps[step];$('#walkthrough').innerHTML=`<div class="walkthrough-visual">${t==='fold'?foldDrawing(kind,step):recipeDrawing(t,step)}</div><div class="step-progress" aria-label="手順${step+1} / ${r.steps.length}">${r.steps.map((_,i)=>`<button data-step="${i}" class="${i===step?'active':''}" aria-label="手順${i+1}へ">${i+1}</button>`).join('')}</div><div class="step-copy" aria-live="polite"><small>STEP ${String(step+1).padStart(2,'0')} / ${r.steps.length}</small><h3>${s[0]}</h3><p>${s[1]}</p></div><div class="step-controls"><button id="step-prev" class="secondary" ${step===0?'disabled':''}>← 前へ</button><button id="step-next" class="primary">${step===r.steps.length-1?'もう一度見る ↻':'次の手順 →'}</button></div>`;$('#step-prev').onclick=()=>{step=Math.max(0,step-1);walkthrough()};$('#step-next').onclick=()=>{step=(step+1)%r.steps.length;walkthrough()};$$('[data-step]',$('#walkthrough')).forEach(b=>b.onclick=()=>{step=Number(b.dataset.step);walkthrough()})}if(t==='fold'||t==='eggs'||t==='salad'){walkthrough();$$('[data-fold-kind]').forEach(b=>b.onclick=()=>{kind=b.dataset.foldKind;step=0;$$('[data-fold-kind]').forEach(x=>x.classList.toggle('active',x===b));walkthrough()})}
if(t==='noise'){function plot(){const phase=Number($('#phase').value),rad=phase*Math.PI/180;$('#phase-out').textContent=phase+'°';let path=(fn,base)=>Array.from({length:161},(_,i)=>`${i?'L':'M'}${40+i*3},${base-fn(i/160*Math.PI*6)*19}`).join(' ');$('#noise-plot').innerHTML=`<text x="7" y="28" font-size="10" fill="#71816c">元の音と追加する音</text><path d="${path(Math.sin,78)}" fill="none" stroke="#a3aaa0" stroke-width="2"/><path d="${path(x=>Math.sin(x+rad),78)}" fill="none" stroke="#5d8964" stroke-width="2"/><path d="M40 175h480" stroke="#cbd3c5" stroke-dasharray="4 4"/><text x="7" y="140" font-size="10" fill="#71816c">合成した波</text><path d="${path(x=>Math.sin(x)+Math.sin(x+rad),175)}" fill="none" stroke="#ad7d45" stroke-width="3"/>`;}$('#phase').oninput=plot;plot()}
if(t==='plain'){const examples=['通信速度制限の適用後は所定の通信速度となります。','使えるデータ量を超えると、通信が遅くなる場合があります。条件や速度は契約するプランで確認します。','道路にたとえると、「通れなくなる」より「ゆっくり通る」イメージです。ただし、道路そのものが狭くなるわけではありません。実際の速度・条件は契約内容で確認します。'];const show=i=>{$('#explain-example').textContent=examples[i];$$('[data-explain]').forEach(b=>b.classList.toggle('active',Number(b.dataset.explain)===i))};$$('[data-explain]').forEach(b=>b.onclick=()=>show(Number(b.dataset.explain)));show(0)}
if(t==='choice'){const opts=[['Tシャツをたたむ','quick','fold'],['一皿つくる','quick','eggs'],['音で静かにする','wonder','noise'],['時間の歴史へ','wonder','railtime'],['色の錯覚を見る','wonder','color'],['説明を言い換える','quick','plain']];const show=()=>{const axis=$('#choice-axis').value;$('#choice-options').innerHTML=opts.filter(x=>axis==='all'||axis===x[1]).map(x=>`<button class="secondary" data-article="${x[2]}">${x[0]} ↗</button>`).join('')};$('#choice-axis').onchange=show;show()}
if(t==='drying')$('#space-laundry').onclick=()=>{const on=$('#drying-model').classList.toggle('spaced');$('#space-laundry').textContent=on?'もとの間隔へ':'布の間をあけてみる ↔'};
if(t==='camouflage')$('#change-background').onclick=()=>$('#camouflage-model').classList.toggle('plain-background');
if(t==='curveball'){const show=()=>{const s=Number($('#spin').value);$('#spin-out').textContent=s<0?'上向きの力':s>0?'下向きの力':'回転なし';$('#ball-plot').innerHTML=`<path d="M35 100h470" stroke="#bcc9c7" stroke-dasharray="6 6"/><path d="M35 100Q270 100 500 ${100+s*70}" fill="none" stroke="#477584" stroke-width="3"/><circle cx="500" cy="${100+s*70}" r="10" fill="#e7e3d0" stroke="#477584"/><text x="35" y="195" font-size="10" fill="#778784">理想化した力の向きの図・実球の軌道計算ではありません</text>`};$('#spin').oninput=show;show()}}
